/**
 * @file test_grouped_gemm_simple.cpp
 * @brief Unit tests for Grouped GEMM kernels generated by grouped_gemm_instance_builder
 *
 * This test includes kernels generated during CMake configuration by
 * grouped_gemm_instance_builder.py and tests them with problem sizes extracted
 * from the corresponding JSON configuration files.
 */

#include <gtest/gtest.h>
#include <iostream>
#include <memory>
#include <vector>

#include "ck_tile/core.hpp"
#include "ck_tile/host.hpp"
#include "ck_tile/ops/gemm/kernel/grouped_gemm_kernel.hpp"
#include "tile_engine/ops/gemm/grouped_gemm/grouped_gemm_common.hpp"

// The kernel header is included via compile command line with -include flag
// It defines SelectedKernel struct, KERNEL_NAME, and tensor data types

// Adaptive error threshold calculation matching tile_engine's implementation
template <typename ADataType_, typename BDataType_, typename AccDataType_, typename CDataType_>
auto calculate_rtol_atol(const ck_tile::index_t K,
                         const ck_tile::index_t kbatch,
                         const float max_accumulated_value)
{
    using ComputeType =
        std::conditional_t<sizeof(ADataType_) < sizeof(BDataType_), ADataType_, BDataType_>;
    const auto rtol = ck_tile::get_relative_threshold<ComputeType, CDataType_, AccDataType_>(
        ck_tile::integer_divide_ceil(K, kbatch));
    const auto atol = ck_tile::get_absolute_threshold<ComputeType, CDataType_, AccDataType_>(
        max_accumulated_value / kbatch, ck_tile::integer_divide_ceil(K, kbatch));
    const auto rtol_split_k =
        ck_tile::get_relative_threshold<CDataType_, CDataType_, CDataType_>(kbatch);
    const auto atol_split_k = ck_tile::get_absolute_threshold<CDataType_, CDataType_, CDataType_>(
        max_accumulated_value, kbatch);
    return ck_tile::make_tuple(std::max(rtol, rtol_split_k), std::max(atol, atol_split_k));
}

/// @brief Compare results for a single group
template <typename ADataType_, typename BDataType_, typename AccDataType_, typename CDataType_>
bool compare_single_group(std::string instanceName,
                          ck_tile::index_t K,
                          ck_tile::index_t kbatch,
                          ck_tile::HostTensor<CDataType_>& c_dev_result,
                          ck_tile::HostTensor<CDataType_>& c_host_result)
{
    const float max_accumulated_value =
        *std::max_element(c_host_result.mData.begin(), c_host_result.mData.end());
    const auto rtol_atol =
        calculate_rtol_atol<ADataType_, BDataType_, AccDataType_, CDataType_>(
            K, kbatch, max_accumulated_value);
    bool pass = ck_tile::check_err(c_dev_result,
                                   c_host_result,
                                   "Error: Incorrect results!",
                                   rtol_atol.at(ck_tile::number<0>{}),
                                   rtol_atol.at(ck_tile::number<1>{}));

    std::cout << "For " << instanceName << " Relative error threshold is "
              << rtol_atol.at(ck_tile::number<0>{}) << " Absolute error threshold is "
              << rtol_atol.at(ck_tile::number<1>{}) << std::endl;
    std::cout << "The verification result is:" << (pass ? "correct" : "fail") << std::endl;

    return pass;
}

// Test parameter structure for grouped GEMM
struct GroupedGemmTestParams
{
    int m, n, k, split_k;
};

// Include config-specific test parameters (after GroupedGemmTestParams struct is defined)
#ifdef GROUPED_GEMM_TEST_PARAMS_HPP
#include GROUPED_GEMM_TEST_PARAMS_HPP
#endif

class GroupedGemmTileEngineTest : public ::testing::TestWithParam<GroupedGemmTestParams>
{
    protected:
    void SetUp() override
    {
        auto params = GetParam();
        m_          = params.m;
        n_          = params.n;
        k_          = params.k;
        split_k_    = params.split_k;
    }

    int m_, n_, k_, split_k_;
};

TEST_P(GroupedGemmTileEngineTest, BasicFunctionality)
{
    const ALayout layout_a = ALayout{};
    const BLayout layout_b = BLayout{};
    const CLayout layout_c = CLayout{};

    // Use group_count from test config (or default)
#ifdef CONFIG_GROUP_COUNT
    const int group_count = CONFIG_GROUP_COUNT;
#else
    const int group_count = 4;
#endif

    const int split_k = split_k_;

    // Create per-group tensors and device buffers
    std::vector<ck_tile::HostTensor<ADataType>> a_tensors;
    std::vector<ck_tile::HostTensor<BDataType>> b_tensors;
    std::vector<ck_tile::HostTensor<CDataType>> c_dev_results;
    std::vector<ck_tile::HostTensor<CDataType>> c_host_results;

    std::vector<std::unique_ptr<ck_tile::DeviceMem>> a_dev_bufs;
    std::vector<std::unique_ptr<ck_tile::DeviceMem>> b_dev_bufs;
    std::vector<std::unique_ptr<ck_tile::DeviceMem>> c_dev_bufs;

    std::vector<ck_tile::GroupedGemmHostArgs<>> gemm_descs;

    for(int g = 0; g < group_count; ++g)
    {
        // Vary dimensions slightly per group for better coverage
        int M = m_ + g * 16;
        int N = n_ + g * 16;
        int K = k_;

        int stride_a = ck_tile::get_default_stride(M, K, 0, is_row_major(layout_a));
        int stride_b = ck_tile::get_default_stride(K, N, 0, is_row_major(layout_b));
        int stride_c = ck_tile::get_default_stride(M, N, 0, is_row_major(layout_c));

        a_tensors.emplace_back(
            ck_tile::host_tensor_descriptor(M, K, stride_a, is_row_major(layout_a)));
        b_tensors.emplace_back(
            ck_tile::host_tensor_descriptor(K, N, stride_b, is_row_major(layout_b)));
        c_dev_results.emplace_back(
            ck_tile::host_tensor_descriptor(M, N, stride_c, is_row_major(layout_c)));
        c_host_results.emplace_back(
            ck_tile::host_tensor_descriptor(M, N, stride_c, is_row_major(layout_c)));

        ck_tile::FillUniformDistribution<ADataType>{-1.f, 1.f}(a_tensors.back());
        ck_tile::FillUniformDistribution<BDataType>{-1.f, 1.f}(b_tensors.back());

        a_dev_bufs.emplace_back(
            std::make_unique<ck_tile::DeviceMem>(a_tensors.back().get_element_space_size_in_bytes()));
        b_dev_bufs.emplace_back(
            std::make_unique<ck_tile::DeviceMem>(b_tensors.back().get_element_space_size_in_bytes()));
        c_dev_bufs.emplace_back(
            std::make_unique<ck_tile::DeviceMem>(c_dev_results.back().get_element_space_size_in_bytes()));

        a_dev_bufs.back()->ToDevice(a_tensors.back().data());
        b_dev_bufs.back()->ToDevice(b_tensors.back().data());
        c_dev_bufs.back()->SetZero();
        c_dev_results.back().SetZero();

        // Compute host reference
        c_host_results.back().SetZero();
        ck_tile::reference_gemm<ADataType, BDataType, AccDataType, CDataType>(
            a_tensors.back(), b_tensors.back(), c_host_results.back());

        gemm_descs.emplace_back(a_dev_bufs.back()->GetDeviceBuffer(),
                                b_dev_bufs.back()->GetDeviceBuffer(),
                                std::array<const void*, 0>{},
                                c_dev_bufs.back()->GetDeviceBuffer(),
                                split_k,
                                M,
                                N,
                                K,
                                stride_a,
                                stride_b,
                                std::array<ck_tile::index_t, 0>{},
                                stride_c);
    }

    // Allocate device memory for kernel arguments
    ck_tile::DeviceMem kargs_buf(sizeof(ck_tile::GemmTransKernelArg<>) * group_count * 2);
    kargs_buf.SetZero();

    ck_tile::stream_config stream_config{nullptr, false, 0, 0, 1, false, false, 1};

    try
    {
        SelectedKernel::launch(gemm_descs, stream_config, kargs_buf.GetDeviceBuffer());
    }
    catch(const std::exception& e)
    {
        std::string error_msg(e.what());
        if(error_msg.find("Arguments not supported") != std::string::npos)
        {
            GTEST_SKIP() << "Configuration not supported: " << e.what();
        }
        else
        {
            FAIL() << "Kernel launch failed: " << e.what();
        }
    }

    // Verify results per group
    bool all_passed = true;
    for(int g = 0; g < group_count; ++g)
    {
        c_dev_bufs[g]->FromDevice(c_dev_results[g].data());

        std::string group_name =
            std::string(KERNEL_NAME) + "[group" + std::to_string(g) + "]";
        bool pass =
            compare_single_group<ADataType, BDataType, AccDataType, CDataType>(
                group_name, k_, split_k, c_dev_results[g], c_host_results[g]);
        all_passed &= pass;
    }

    EXPECT_TRUE(all_passed) << "Grouped GEMM result verification failed";
}

TEST_P(GroupedGemmTileEngineTest, KernelInfo)
{
    EXPECT_TRUE(strlen(KERNEL_NAME) > 0) << "Kernel name should not be empty";

    std::cout << "Testing kernel: " << KERNEL_NAME << std::endl;
    std::cout << "Problem size: " << m_ << "x" << n_ << "x" << k_ << " with split_k=" << split_k_
              << std::endl;
}

INSTANTIATE_TEST_SUITE_P(
    GroupedGemmVerification,
    GroupedGemmTileEngineTest,
    ::testing::ValuesIn(CONFIG_TEST_PARAMS),
    [](const ::testing::TestParamInfo<GroupedGemmTestParams>& param_info) {
        return std::to_string(param_info.param.m) + "x" +
               std::to_string(param_info.param.n) + "x" +
               std::to_string(param_info.param.k) + "_splitk" +
               std::to_string(param_info.param.split_k);
    });
